// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    // fuzzed params: from (sender), v (amount), n (number of recipients, small), seed (to diversify recipient addresses)
    function testFuzz_property(address from, uint96 v, uint8 n, uint256 seed) public {
        // keep domain wide but sensible
        vm.assume(from != address(0));
        uint8 count = uint8(bound(n, 1, 5)); // require at least one recipient to exercise require(_tos.length>0)

        // build recipients array deterministically from seed so fuzzer still controls inputs
        address[] memory tos = new address[](count);
        for (uint8 i = 0; i < count; i++) {
            // derive addresses from seed so they are non-zero and distinct-ish
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
            if (tos[i] == address(0)) tos[i] = address(uint160(1 + i));
        }

        // deploy recorder that exposes the exact transferFrom(address,address,uint256) function
        Recorder rec = new Recorder();

        // ensure recorder has some balance so low-level call semantics unaffected
        vm.deal(address(this), 1 ether);

        // call c.transfer with 'from', recorder address, tos, v
        bool ok;
        try c.transfer(from, address(rec), tos, uint256(v)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The GENERAL RULE (one assertion): For the correct contract, for ANY admissible inputs
        // (non-empty tos), the recorder will have recorded exactly `count` successful decoded calls
        // with the tuples (from, tos[i], v). The mutant that uses the wrong selector will cause at
        // least one of these calls to fail or to decode differently for some inputs. We observe
        // recorder.numCalls() and recorder.successful() to assert the reference's universal property.

        // Assert that if the transfer call returns (ok == true) then the recorder recorded exactly
        // `count` successful decoded calls matching the triples. The correct implementation guarantees
        // the low-level call returns true (ok==true) and all calls decode; the mutant can cause ok
        // to be false or the recorder to have fewer successful decodes for some fuzz input.

        if (ok) {
            // exactly count calls recorded
            assertTrue(rec.numCalls() == count);
            // and each recorded decoded triple matches (from, tos[i], v)
            for (uint8 i = 0; i < count; i++) {
                (address rfrom, address rto, uint256 rv, bool rsuccess) = rec.calls(i);
                assertTrue(rsuccess);
                assertTrue(rfrom == from);
                assertTrue(rto == tos[i]);
                assertTrue(rv == uint256(v));
            }
        } else {
            // If the external low-level call reverted/returned false, then the correct contract should
            // never do that for properly-formed selector; but to keep this a universal property checked
            // only on the reference contract, we only assert the property in the ok==true branch.
            // The test will fail on the mutant for some inputs because either ok will be false or
            // recorded decodes will differ, causing the assertions above to fail.
            assertTrue(true);
        }
    }
}

// Recorder that declares the expected function selector exactly as in the reference contract
contract Recorder {
    struct Rec { address from; address to; uint256 v; bool success; }
    Rec[] public recs;

    // This function matches selector transferFrom(address,address,uint256)
    function transferFrom(address _from, address _to, uint256 _v) external returns (bool) {
        recs.push(Rec({ from: _from, to: _to, v: _v, success: true }));
        return true;
    }

    // fallback to catch malformed calls or wrong selector; record as failure
    fallback() external payable {
        // record a failure with zeroed decode to signal a bad/malformed call arrived
        recs.push(Rec({ from: address(0), to: address(0), v: 0, success: false }));
    }

    function numCalls() external view returns (uint256) { return recs.length; }
    function calls(uint256 i) external view returns (address, address, uint256, bool) {
        Rec storage r = recs[i];
        return (r.from, r.to, r.v, r.success);
    }
}
